solution.solution.cpp:
int stackHeight(int stones, int stonesPerLayer)
{
    if (stonesPerLayer <= 0 || stones <= 0) return 0;
    return (stones + stonesPerLayer - 1) / stonesPerLayer;
}

double stackWeight(int stones, double kilosEach)
{
    return stones * kilosEach;
}

unitTests:
TEST("the example") { CHECK_EQ(stackHeight(10, 4), 3); CHECK_NEAR(stackWeight(10, 2.5), 25.0, 1e-9); }
TEST("exact layers") { CHECK_EQ(stackHeight(12, 4), 3); CHECK_EQ(stackHeight(1, 1), 1); }
TEST("part layer") { CHECK_EQ(stackHeight(13, 4), 4); CHECK_EQ(stackHeight(1, 10), 1); }
TEST("nothing to stack") { CHECK_EQ(stackHeight(0, 4), 0); CHECK_EQ(stackHeight(5, 0), 0); CHECK_EQ(stackHeight(5, -2), 0); }
TEST("weight") { CHECK_NEAR(stackWeight(3, 1.5), 4.5, 1e-9); CHECK_NEAR(stackWeight(0, 9.0), 0.0, 1e-9); }

